{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
if (dbPath !== ':memory:') mkdirSync(dirname(dbPath), { recursive: true });
const database = new DatabaseSync(dbPath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);
// Keep databases created by earlier Workboard versions compatible.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}

const listProjects = database.prepare(`SELECT p.id, p.name, p.archived,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
  FROM projects p WHERE p.archived = ? ORDER BY p.id`);
const getProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProjectArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
const listTasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const getTask = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');

function sendJson(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body || '{}');
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, listProjects.all(url.searchParams.get('filter') === 'Archived' ? 1 : 0));
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const { name } = await readBody(request);
      const cleanName = typeof name === 'string' ? name.trim() : '';
      if (!cleanName) return sendJson(response, 400, { error: 'Project name is required' });
      const result = createProject.run(cleanName);
      return sendJson(response, 201, getProject.get(Number(result.lastInsertRowid)));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'PATCH' && projectMatch) {
    try {
      const projectId = Number(projectMatch[1]);
      const body = await readBody(request);
      if (typeof body.name === 'string') {
        const cleanName = body.name.trim();
        if (!cleanName) return sendJson(response, 400, { error: 'Project name is required' });
        const currentProject = getProject.get(projectId);
        if (!currentProject) return sendJson(response, 404, { error: 'Project not found' });
        if (currentProject.archived) return sendJson(response, 400, { error: 'Archived projects cannot be renamed' });
        renameProject.run(cleanName, projectId);
      } else if (typeof body.archived === 'boolean') {
        updateProjectArchive.run(body.archived ? 1 : 0, projectId);
      } else {
        return sendJson(response, 400, { error: 'Invalid project update' });
      }
      const project = getProject.get(projectId);
      return project ? sendJson(response, 200, project) : sendJson(response, 404, { error: 'Project not found' });
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  if (request.method === 'GET' && projectMatch) {
    const project = getProject.get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, project) : sendJson(response, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (request.method === 'GET' && tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!getProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, listTasks.all(projectId));
  }
  if (request.method === 'POST' && tasksMatch) {
    try {
      const projectId = Number(tasksMatch[1]);
      const project = getProject.get(projectId);
      if (!project) return sendJson(response, 404, { error: 'Project not found' });
      if (project.archived) return sendJson(response, 400, { error: 'Archived projects cannot be changed' });
      const { title } = await readBody(request);
      const cleanTitle = typeof title === 'string' ? title.trim() : '';
      if (!cleanTitle) return sendJson(response, 400, { error: 'Task title is required' });
      const result = createTask.run(projectId, cleanTitle);
      return sendJson(response, 201, getTask.get(Number(result.lastInsertRowid), projectId));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (request.method === 'PATCH' && taskMatch) {
    try {
      const projectId = Number(taskMatch[1]);
      const taskId = Number(taskMatch[2]);
      const project = getProject.get(projectId);
      if (!project) return sendJson(response, 404, { error: 'Project not found' });
      if (project.archived) return sendJson(response, 400, { error: 'Archived projects cannot be changed' });
      const body = await readBody(request);
      if (typeof body.title === 'string') {
        const cleanTitle = body.title.trim();
        if (!cleanTitle) return sendJson(response, 400, { error: 'Task title is required' });
        renameTask.run(cleanTitle, taskId, projectId);
      } else if (typeof body.completed === 'boolean') {
        updateTask.run(body.completed ? 1 : 0, taskId, projectId);
      } else {
        return sendJson(response, 400, { error: 'Invalid task update' });
      }
      const task = getTask.get(taskId, projectId);
      return task ? sendJson(response, 200, task) : sendJson(response, 404, { error: 'Task not found' });
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    try {
      const page = await readFile(join(root, 'public', 'index.html'));
      response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return response.end(page);
    } catch {
      response.writeHead(500);
      return response.end('Application unavailable');
    }
  }
  if (request.method === 'GET' && ['/app.js', '/styles.css'].includes(url.pathname)) {
    const type = url.pathname.endsWith('.js') ? 'text/javascript; charset=utf-8' : 'text/css; charset=utf-8';
    try {
      const content = await readFile(join(root, 'public', url.pathname.slice(1)));
      response.writeHead(200, { 'Content-Type': type });
      return response.end(content);
    } catch {
      response.writeHead(404);
      return response.end('Not found');
    }
  }
  response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

const port = Number(process.env.PORT) || 8080;
server.listen(port, '0.0.0.0');
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const form = document.querySelector('#project-form');
const nameInput = document.querySelector('#project-name');
const alert = document.querySelector('#form-alert');
const projectsContainer = document.querySelector('#projects');
const projectFilter = document.querySelector('#project-filter');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const taskFilter = document.querySelector('#task-filter');
const tasksContainer = document.querySelector('#tasks');
const renameForm = document.querySelector('#rename-form');
const renameInput = document.querySelector('#new-project-name');
const renameAlert = document.querySelector('#rename-alert');
let activeProjectId = null;
let activeProjectArchived = false;

async function request(path, options) {
  const response = await fetch(path, options);
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || 'Request failed');
  return value;
}

function showList() {
  listView.hidden = false;
  detailView.hidden = true;
  document.title = 'Workboard';
}

async function renderProjects() {
  const archived = projectFilter.value === 'Archived';
  const projects = await request(`/api/projects?filter=${projectFilter.value}`);
  projectsContainer.replaceChildren();
  for (const project of projects) {
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const openButton = document.createElement('button');
    openButton.type = 'button';
    openButton.textContent = 'Open project';
    openButton.addEventListener('click', () => navigate(`/projects/${project.id}`));
    row.append(name, summary, openButton);
    const archiveButton = document.createElement('button');
    archiveButton.type = 'button';
    archiveButton.textContent = archived ? 'Restore project' : 'Archive project';
    archiveButton.addEventListener('click', async () => {
      await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !archived }),
      });
      await renderProjects();
    });
    row.append(archiveButton);
    projectsContainer.append(row);
  }
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (!match) {
    showList();
    await renderProjects();
    return;
  }
  const project = await request(`/api/projects/${match[1]}`);
  activeProjectId = project.id;
  activeProjectArchived = Boolean(project.archived);
  document.querySelector('#project-title').textContent = project.name;
  document.title = `${project.name} · Workboard`;
  listView.hidden = true;
  detailView.hidden = false;
  document.querySelector('#archived-label').hidden = !activeProjectArchived;
  renameInput.disabled = activeProjectArchived;
  renameForm.querySelector('button').disabled = activeProjectArchived;
  taskInput.disabled = activeProjectArchived;
  taskForm.querySelector('button').disabled = activeProjectArchived;
  await renderTasks();
}

async function renderTasks() {
  if (activeProjectId === null) return;
  const tasks = await request(`/api/projects/${activeProjectId}/tasks`);
  const filter = taskFilter.value;
  tasksContainer.replaceChildren();
  for (const task of tasks) {
    if (filter === 'Open' && task.completed) continue;
    if (filter === 'Completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const label = document.createElement('label');
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.disabled = activeProjectArchived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      try {
        await request(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        await renderTasks();
      } catch (error) {
        taskAlert.textContent = error.message;
        taskAlert.hidden = false;
      }
    });
    label.append(checkbox);
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.setAttribute('aria-label', 'New task title');
    renameInput.value = task.title;
    renameInput.disabled = activeProjectArchived;
    const renameButton = document.createElement('button');
    renameButton.type = 'button';
    renameButton.textContent = 'Rename task';
    renameButton.disabled = activeProjectArchived;
    renameButton.addEventListener('click', async () => {
      taskAlert.hidden = true;
      try {
        await request(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title: renameInput.value }),
        });
        await renderTasks();
      } catch (error) {
        taskAlert.textContent = error.message;
        taskAlert.hidden = false;
      }
    });
    row.append(title, label, renameInput, renameButton);
    tasksContainer.append(row);
  }
}

function navigate(path) {
  history.pushState({}, '', path);
  renderRoute().catch(showList);
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  alert.hidden = true;
  try {
    const project = await request('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: nameInput.value }),
    });
    nameInput.value = '';
    await renderProjects();
    nameInput.focus();
    return project;
  } catch (error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
});

document.querySelector('#back-button').addEventListener('click', () => navigate('/'));
renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  renameAlert.hidden = true;
  try {
    const project = await request(`/api/projects/${activeProjectId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: renameInput.value }),
    });
    renameInput.value = '';
    document.querySelector('#project-title').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    renameInput.focus();
  } catch (error) {
    renameAlert.textContent = error.message;
    renameAlert.hidden = false;
  }
});
projectFilter.addEventListener('change', () => renderProjects().catch(() => {}));
taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  taskAlert.hidden = true;
  try {
    await request(`/api/projects/${activeProjectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: taskInput.value }),
    });
    taskInput.value = '';
    await renderTasks();
    taskInput.focus();
  } catch (error) {
    taskAlert.textContent = error.message;
    taskAlert.hidden = false;
  }
});
taskFilter.addEventListener('change', () => renderTasks().catch((error) => {
  taskAlert.textContent = error.message;
  taskAlert.hidden = false;
}));
window.addEventListener('popstate', () => renderRoute().catch(showList));
renderRoute().catch(showList);
